export const NOMBRE_CATALOGO = "Catalogo-de-cabello.pdf";

export const PIE_CATALOGO =
  "Ve el catálogo de cabello. Están Clip In, Tape In, Hand-Tied, Adam Veil y Ponytail. Para reservar, escribe al WhatsApp 3992 1868.";

const BASE64 =
  "";

export function bytesCatalogo(): Uint8Array {
  const binario = atob(BASE64);
  const bytes = new Uint8Array(binario.length);
  for (let i = 0; i < binario.length; i++) bytes[i] = binario.charCodeAt(i);
  return bytes;
}
